  user_id UUID PRIMARY KEY,
  preferences JSONB NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Query to retrieve preferences by user_id
-- This query benefits from primary key index on user_id
